                                	case Some((at2: ArrowType,sp2,_)) =>
                                	// the domain of the pair's declaration written first, whatever the order of the set
                                	val (shown, shownSp) = if (writtenBefore(at2, at)) (at2, sp2) else (at, sp)
                                	error(mergeSpan(at, at2),
                                			"There are multiple declarations of " +
                                					name + " with the same parameter type: " + (shownSp match {
                                                                          // a functional method's domain without self, wherever it sits
                                                                          case Some(i) if isMethod => globalOracle.sa.makeDomainFromArrow(withoutSelf(shown, i), false)
                                                                          case _ => globalOracle.sa.makeDomainFromArrow(shown, isMethod) }))
                                	case None =>	
                              }	
                              // a dotted method's parameters are those after its receiver
                              val params = if (isMethod && sp.isEmpty) dropReceiver(at.getDomain) else at.getDomain
                              if ( checkBoundAny(params, toListFromImmutable(at.getInfo.getStaticParams)) ) {
                                		error(NU.getSpan(at), "A functional which takes a single parameter " +
                                				"of a parametric type bound by Any\n    cannot be overloaded.")
                              }
                                	signatures = sig :: signatures
                           }
                           var index = 1
                           for ( first <- signatures ) {
                               signatures.slice(index, signatures.length).foreach(second => {
                                       val a1 = validOverloading(first, second, signatures, isMethod, oracle)
                                      /* if (false) {
                                           val a2 = validOverloading(first, second, signatures, isMethod, oracle)
                                           val a3 = validOverloading(first, second, signatures, isMethod, oracle)
