    /* The Meet Rule for Functional Methods: two functional methods with their self
     * parameters at one position are a valid overloading among the top-level functionals;
     * the meet the rule asks of a trait or object that provides both is checked for that
     * trait or object (checkOverloading's loop over them). */
    private def functionalMethodsAtOnePosition(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                                               second: (ArrowType,Option[Int],Option[JavaFunctional]),
                                               isMethod: Boolean): Boolean =
      !isMethod && first._2.isDefined && first._2 == second._2 &&
      first._3.exists(isFunctionalMethod) && second._3.exists(isFunctionalMethod)

    private def meetRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
    	                 second: (ArrowType,Option[Int],Option[JavaFunctional]),
			 signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
			 isMethod: Boolean,
			 oa: OverloadingOracle,
			 debug : Boolean = false): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      val b1 = fsp == gsp
      val b2 = (fsp == gsp) &&
      signatures.exists(third => third match {
           case (ha, hsp, _) => {
              val a1 = (hsp == fsp) 
              val a2 = a1 && oa.lteq(ha, fa) 
              val a3 = a2 && oa.lteq(ha, ga) 
              val a4 = a3 && (if (isMethod && fsp.isDefined)
                                oa.isMeet(withoutSelf(ha, fsp.get), withoutSelf(fa, fsp.get), withoutSelf(ga, fsp.get), false, debug)
                              else oa.isMeet(ha, fa, ga, isMethod, debug))
     //         if (debug)
     //             println("" + ha + " " + a1 + a2 + a3 + a4)

              a4}})
      b2
    }

    // the self parameter of a functional method is compared as a dotted method's receiver is, wherever it sits
    private def withoutSelf(a: ArrowType, i: Int): ArrowType = {
      val d = a.getDomain match {
        case t: TupleType =>
          NF.makeTupleType(NU.getSpan(t), toJavaList(toListFromImmutable(t.getElements).zipWithIndex.filter(_._2 != i).map(_._1)))
        case t => NF.makeTupleType(NU.getSpan(t), toJavaList(List[Type]()))
      }
      NF.makeArrowType(NU.getSpan(a), d, a.getRange, a.getInfo.getStaticParams)
    }

    /* The Meet Rule's closed-trait case, for functions and functional methods: the
     * declarations whose domains are below both domains together hold every value of
     * their overlap, as the comprises clauses show (OverloadingOracle.coversOverlap).
     * For functional methods of a trait or object that provides them, the overlap is
     * read without the self parameter, as meetRule reads the meet. */
    private def coverageRule(first: (ArrowType,Option[Int],Option[JavaFunctional]),
                             second: (ArrowType,Option[Int],Option[JavaFunctional]),
                             signatures: List[(ArrowType,Option[Int],Option[JavaFunctional])],
                             isMethod: Boolean,
                             oa: OverloadingOracle): Boolean = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      if (fsp != gsp || (isMethod && fsp.isEmpty)) false
      else {
        val hs = signatures.collect {
          case (ha, hsp, _) if hsp == fsp && !(ha eq fa) && !(ha eq ga) &&
                               oa.lteq(ha, fa) && oa.lteq(ha, ga) => ha }
        if (isMethod) {
          val i = fsp.get
          oa.coversOverlap(withoutSelf(fa, i), withoutSelf(ga, i), hs.map(withoutSelf(_, i)))
        }
        else oa.coversOverlap(fa, ga, hs)
      }
    }

    /* The return types of a declaration o and of a declaration p that it keeps the type
     * declaring it from inheriting (STypesUtil.providedAndOverridden). Where their parameter
     * types are the same, the two are checked as the pair of an overloading was, o being the
     * more specific; where o has the modifier override and widens p's, o's return type must be
     * a subtype of p's (traits.tex, "Method Declarations"): with static parameters, at every
     * instance of p, and where both declare as many of their own, also position by position. */
    private def checkOverridingReturnType(name: IdOrOpOrAnonymousName,
                                          o: (JavaFunctional, StaticTypeReplacer, TraitType),
                                          p: (JavaFunctional, StaticTypeReplacer, TraitType),
                                          equal: Boolean,
                                          oracle: OverloadingOracle): Unit = {
      def arrow(d: (JavaFunctional, StaticTypeReplacer, TraitType)) =
        if (isFunctionalMethod(d._1)) toFunctionalMethodArrows(Set(d), oracle).headOption
        else toMethodArrows(Set(d)).headOption
      (arrow(o), arrow(p)) match {
        case (Some(oa), Some(pa)) =>
          if (equal) {
            returnTypeCheck(name, oa, pa, oracle)
            returnTypeCheck(name, pa, oa, oracle)
          } else {
            def own(a: ArrowType) = toListFromImmutable(a.getInfo.getStaticParams).filter(!_.isLifted)
            // the self parameter, or a dotted method's receiver, apart
            val at = oa._2.getOrElse(0)
            val holds =
              if (own(oa._1).isEmpty && own(pa._1).isEmpty)
                isTrue(typeAnalyzer.subtype(oa._1.getRange, pa._1.getRange))(typeAnalyzer)
              else oracle.sa.subtypeUA(withoutSelf(oa._1, at), withoutSelf(pa._1, at)) &&
                   oracle.satisfiesPositionalRule(oa._1, pa._1)
            if (!holds)
              error(mergeSpan(oa._1, pa._1),
                    "For " + name + ",\nthe return type of the overriding declaration " + typeAndSpanToString(oa._1) +
                    " should be a subtype of the\n    return type of the declaration it overrides " + typeAndSpanToString(pa._1))
          }
        case _ =>
      }
    }

    private def returnTypeCheck(name: IdOrOpOrAnonymousName,
    	    			first: (ArrowType,Option[Int],Option[JavaFunctional]),
                                second: (ArrowType,Option[Int],Option[JavaFunctional]),
			        oa: OverloadingOracle) = {
      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
//          println("Satisfies return type rule?\n   " + typeAndSpanToString(fa) + "\n   " + typeAndSpanToString(ga))
      if (!oa.satisfiesReturnTypeRule(fa, ga)) {
//        println("For " + name + ",\nthe return type of " + typeAndSpanToString(fa) + " should be a subtype of the\n    return type of " + typeAndSpanToString(ga))
        error(mergeSpan(fa, ga),
	      "For " + name + ",\nthe return type of " + typeAndSpanToString(fa) + " should be a subtype of the\n    return type of " + typeAndSpanToString(ga))
      }
      else if (oa.lteq(fa, ga) && !oa.satisfiesPositionalRule(fa, ga))
        error(mergeSpan(fa, ga),
              "For " + name + ",\nthe static parameters of " + typeAndSpanToString(fa) + " should correspond position by position\n    to those of " + typeAndSpanToString(ga) +
              ":\n    of the same kinds, with a return type that is a subtype of the other's under that correspondence.")
    }


    /* Drop the first element denoting the receiver type of the given type. */
    private def dropReceiver(param: Type) = param match {
      case STupleType(info, _::ty::Nil, None, Nil) => ty
      case STupleType(info, elements, varargs, keywords) =>
        STupleType(info, elements.takeRight(elements.size-1), varargs, keywords)
      case _ => NodeFactory.makeVoidType(NU.getSpan(param))
    }

    def isDeclaredName(f: IdOrOpOrAnonymousName) = f match {
        case SId(_,_,str) => IdentifierUtil.validId(str)
        case SOp(_,_,str,_,_) => NU.validOp(str)
        case _ => false
    }

    def isDeclaredMethod(f: JavaFunctional) = f match {
        case SDeclaredMethod(_,_) => true
        case _ => false
    }

    def isFunction(f: JavaFunctional) = f match {
        case SDeclaredFunction(_) => true
        case SFunctionalMethod(_,_) => true
        case SConstructor(_,_,_,_,_) => true
        case _ => false
    }
